if doc.item_group and doc.is_new():

    item_group_name = str(doc.item_group).strip()

    series_map = {
        "Raw Material": {
            "start": 1000000,
            "end": 1099999
        },
        "Semi finished goods": {
            "start": 1600000,
            "end": 1699999
        },
        "Finished Goods": {
            "start": 2000000,
            "end": 2099999
        },
        "Finished Good": {
            "start": 2000000,
            "end": 2099999
        }
    }

    if item_group_name in series_map:
        start_no = series_map[item_group_name]["start"]
        end_no = series_map[item_group_name]["end"]

        latest_items = frappe.get_all(
            "Item",
            filters={
                "item_group": item_group_name
            },
            fields=["item_code"],
            limit_page_length=1000
        )

        latest_code = start_no - 1

        for item in latest_items:
            item_code = str(item.item_code or "").strip()

            if item_code.isdigit():
                code = int(item_code)

                if code >= start_no and code <= end_no and code > latest_code:
                    latest_code = code

        next_code = latest_code + 1

        if next_code > end_no:
            frappe.throw("Item Code series completed for " + item_group_name)

        doc.item_code = str(next_code)
        doc.custom_item_code_series = str(start_no)

for row in doc.items:
    if row.item_code and row.batch_no:
        item_has_batch = frappe.db.get_value("Item", row.item_code, "has_batch_no")

        if item_has_batch:
            batch_exists = frappe.db.exists("Batch", row.batch_no)

            if not batch_exists:
                batch = frappe.new_doc("Batch")
                batch.batch_id = row.batch_no
                batch.item = row.item_code
                batch.insert(ignore_permissions=True)
